# Conditional, actually delivered value strategies remain covered after normalization/dedup.
for name in ['easy','moderate']:
 ss=load(R/'delivery-coverage.json')[name]['shortcut_probes']
 for x in ss:
  if x['subgroup']=='target:zero' and x['strategy']=='No solution':probe(x,'delivery-'+name+'/accepted.json','Homogeneous prompts now yield numeric scalars as well as No solution; zero-RHS wording no longer fixes the correct choice.')
