  probes.append({'cue':'actual UI answer position','subgroup':pool+'; synthetic item id '+str(x['task_item_id_assumption']),'scope':'other_recognizable_subgroup','strategy':'choose displayed position '+str(x['position']+1),'correct':x['correct'],'total':x['total'],'baseline':0.2,'disposition':'not_predictive','conclusion':'Baseline is uniform blind choice among five options. Uses the actual UI FNV ordering, verified against 29 HTML previews; future real task-item IDs are unavailable. None of the tested constant UI positions answers the entire batch or an entire 16-case profile.','sample_refs':[pool,'ui-order-results.json']})
