for r in normal:
 ans,res,(_,u,_,_,_)=a.solve(r['question'])
 if any(y==0 and x!=0 for x,y in zip(res,u)):math_simplification.append(r)
if math_simplification:
 save('zero-component-contradictions.json',math_simplification)
 probes.append({'cue':'zero unknown-vector component has nonzero residual','subgroup':'homogeneous component contradictions','scope':'within_template','strategy':'select No solution after computing/inspecting that component equation','correct':len(math_simplification),'total':len(math_simplification),'baseline':0.2,'disposition':'intended_skill','conclusion':'Blind-choice baseline is 0.2. This perfect rule is the mathematical consistency test itself: 0 times the scalar cannot equal a nonzero residual. Source homogeneous worked solutions require component agreement, so this is a valid simplification, not an incidental shape cue.','sample_refs':['zero-component-contradictions.json','normal-records.json']})
ped={'learner_operation':source['learner_operation'],'fixed_features':[{'feature':'one unknown scalar, nonzero unknown vector, equal dimensions','justification':'Canonical example and lesson isolate one coefficient; a nonzero vector avoids an unsupported infinite-solutions response.'},{'feature':'2–4 coordinates and one five-choice radio field','justification':'All 13 captured question banks have this response shape; dimension bounded by source workload.'},{'feature':'easy sampler has unique scalars; moderate sampler varies consistency','justification':'All eight complete easy cases focus on finding a scalar; moderate source worked solutions explicitly add consistency/contradiction checking. Keeping easy as this narrower focused operation is instructional, while homogeneous wording within moderate must not fix its outcome.'},{'feature':'subtraction coefficient c=1','justification':'The displayed subtraction family is a1-x*a2=b, so enforcing c=1 keeps prompt and arithmetic coherent. General addition coefficient still varies.'}],'answer_roles':[{'role':'correct scalar and its bank rank/sign/position','eligible_variation':'Any numeric role in a held bank may be correct; relabeling unknown is cosmetic.','observed':'56 held-bank role records plus 192 normal samples; every profile reaches all five stored positions, labels vary, positive/negative values occur, and many profiles reach zero.'},{'role':'homogeneous consistency outcome','eligible_variation':'Changing one unknown-vector component may switch No solution to a numeric scalar without changing the form or bank.','observed':'Exact prior one-coordinate witness now gives -6; all four moderate profiles show both outcomes in fresh normal and delivered samples.'},{'role':'informative and contradictory component','eligible_variation':'Any coordinate can supply first nonzero information or a mismatch; no mathematical reason fixes the first row.','observed':'Moderate normal samples reach all possible first-informative coordinates. Mismatches and zero components checked from visible equations; no stale key/solution found.'}],'coverage':coverage,'counterfactuals':cf,'shortcut_probes':probes,'delivery':{'stages_examined':['generator input validation','normal construction and rejection/resampling','within-batch mathematical fingerprint deduplication','requested difficulty','actual publisher normalization/validation/stable identities','captured inventory and within-batch publication deduplication','learner freshness/usability prefilter and weighted same-band selection','actual UI answer ordering'],'sample_refs':['resampling-results.json','resampling-easy.json','resampling-moderate.json','delivery-easy/delivery.json','delivery-moderate/delivery.json','delivery-batch/delivery.json','delivery-coverage.json','selection-results.json','inventory-selection-results.json','ui-order-results.json'],'result':'20/20 attempts accepted in each instrumented normal batch. Publisher accepts 128/128 easy,64/64 moderate and5/5 exact runner records against inventory basis5398; cases/shortcuts unchanged by delivery. Read-only weighted selection scenarios retain access to both moderate outcomes in fresh delivered controls. Captured legacy moderate inventory remains all No solution and is explicitly not claimed remediated.'},'limitations':['Finite source-grounded audit does not prove absence of every possible shortcut.','No live learner histories or active policy weights captured; candidate selection scenarios use stated synthetic IDs and positive requested-band weights, with a second half-excluded scenario. No actual future task draw is claimed.','Two legacy v1.0.0 generated inventory records reproduce the prior homogeneous-family weakness. They are saved in affected-inventory.json; acceptance of v1.1.0 does not claim database repair. The requested new batch is easy only.','The five runner answers are all negative and three equal -2; no tested complete sign/rank/label/position shortcut answers the entire batch, and each item has multiple negative choices.','Incomplete unrated q-34250 has no authored key/solution. Implied answer4 is identified as inference; no missing source fields invented.','Source canonical example lacks an answer bank; mathematical prompt/solution replay uses a clearly authored bank.','Actual free-entry equivalence does not apply to this source radio-response contract. Every choice, including every plausible distractor, was exercised through the native learner grader.']}
